<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>About Me Card - Mobile View</title>
    <style>
        :root {
            --bg-color: #ffffff;
            --text-primary: #111827;
            --text-secondary: #6b7280;
            --accent-color: #3b82f6;
            --tag-bg: #f3f4f6;
            --tag-text: #374151;
            --border-color: #e5e7eb;
            --input-bg: #f9fafb;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
            -webkit-font-smoothing: antialiased;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            background-color: var(--bg-color);
            color: var(--text-primary);
            display: flex;
            justify-content: center;
            min-height: 100vh;
            /* Simulating mobile viewport on desktop for the demo */
            max-width: 390px; 
            margin: 0 auto; 
            box-shadow: 0 0 20px rgba(0,0,0,0.05);
            position: relative;
        }

        .container {
            width: 100%;
            padding: 16px;
            padding-bottom: 40px;
            display: flex;
            flex-direction: column;
            gap: 20px;
        }

        /* Header / Back Button */
        .header {
            display: flex;
            align-items: center;
            margin-bottom: 10px;
        }

        .back-btn {
            width: 32px;
            height: 32px;
            border-radius: 50%;
            border: 1px solid var(--border-color);
            background: white;
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            color: var(--text-primary);
        }

        /* Profile Image Section */
        .profile-image-container {
            width: 100%;
            position: relative;
            border-radius: 24px;
            overflow: hidden;
            aspect-ratio: 1/1; /* Square container */
            background-color: #e5e7eb;
        }

        .profile-img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            object-position: top center;
            display: block;
        }

        .status-badge {
            position: absolute;
            bottom: 16px;
            right: 16px;
            background: rgba(255, 255, 255, 0.95);
            backdrop-filter: blur(4px);
            padding: 6px 12px;
            border-radius: 20px;
            font-size: 13px;
            font-weight: 500;
            display: flex;
            align-items: center;
            gap: 6px;
            box-shadow: 0 2px 8px rgba(0,0,0,0.08);
        }

        .status-dot {
            width: 8px;
            height: 8px;
            background-color: #000;
            border-radius: 50%;
        }

        /* Text Info Section */
        .info-section h1 {
            font-size: 24px;
            font-weight: 700;
            margin-bottom: 4px;
            color: var(--text-primary);
        }

        .meta-info {
            font-size: 15px;
            color: var(--text-secondary);
            line-height: 1.5;
            margin-bottom: 20px;
        }

        .bio-text {
            font-size: 16px;
            line-height: 1.6;
            color: var(--text-primary);
        }

        /* Tags Section */
        .tags-container {
            display: flex;
            flex-wrap: wrap;
            gap: 8px;
            overflow-x: auto; /* Allow scroll if needed, though wrapping is preferred */
            padding-bottom: 4px;
        }

        .tag {
            background-color: var(--tag-bg);
            color: var(--tag-text);
            padding: 8px 16px;
            border-radius: 20px;
            font-size: 14px;
            font-weight: 500;
            white-space: nowrap;
        }

        /* Accordion Toggle */
        .accordion-toggle {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 6px;
            color: var(--text-secondary);
            font-size: 14px;
            cursor: pointer;
            margin: 10px 0;
            width: 100%;
            background: none;
            border: none;
            font-family: inherit;
        }

        /* Navigation Grid (Pills) */
        .nav-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr); /* 3 columns as per screenshot */
            gap: 12px;
        }

        .nav-pill {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 6px;
            padding: 10px;
            border: 1px solid var(--border-color);
            border-radius: 20px;
            background: white;
            color: var(--text-primary);
            font-size: 15px;
            font-weight: 500;
            cursor: pointer;
            text-decoration: none;
            transition: background 0.2s;
        }

        .nav-pill:hover {
            background-color: #f9fafb;
        }

        .nav-icon {
            width: 18px;
            height: 18px;
            stroke-width: 2;
        }

        /* Input Area */
        .input-area {
            position: fixed;
            bottom: 0;
            left: 0;
            width: 100%;
            max-width: 390px; /* Match body constraint */
            background: white;
            padding: 12px 16px;
            border-top: 1px solid transparent; /* Visual separation if needed */
            display: flex;
            align-items: center;
            gap: 12px;
            z-index: 100;
        }

        .avatar-small {
            width: 36px;
            height: 36px;
            border-radius: 50%;
            background: #333;
            color: white;
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: 600;
            font-size: 16px;
            flex-shrink: 0;
        }

        .input-wrapper {
            flex-grow: 1;
            position: relative;
            display: flex;
            align-items: center;
        }

        .text-input {
            width: 100%;
            padding: 12px 44px 12px 16px;
            border-radius: 24px;
            border: none;
            background-color: var(--input-bg);
            font-size: 15px;
            outline: none;
            color: var(--text-primary);
        }

        .text-input::placeholder {
            color: #9ca3af;
        }

        .send-btn {
            position: absolute;
            right: 4px;
            top: 50%;
            transform: translateY(-50%);
            width: 34px;
            height: 34px;
            border-radius: 50%;
            background-color: #60a5fa; /* Light blue from screenshot */
            border: none;
            color: white;
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
        }

        /* Utility for icons */
        svg {
            display: block;
        }

    </style>
</head>
<body>

    <div class="container">
        <!-- Header -->
        <div class="header">
            <div class="back-btn">
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                    <path d="M15 18l-6-6 6-6"/>
                </svg>
            </div>
        </div>

        <!-- Profile Image -->
        <div class="profile-image-container">
            <!-- Using a placeholder that resembles a person in a suit -->
            <img src="https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80" alt="Md. Emon Profile" class="profile-img">

            <div class="status-badge">
                <span class="status-dot"></span>
                Open to work
            </div>
        </div>

        <!-- Text Content -->
        <div class="info-section">
            <h1>Md. Emon</h1>
            <div class="meta-info">
                21 years old<br>
                Barishal, Bangladesh
            </div>
            <div class="bio-text">
                Hey, I'm Emon 👋<br><br>
                I'm a backend-focused developer and SaaS builder passionate about building the systems behind modern software. I specialize in backend engineering, APIs, databases, integrations, AI, and automation, while working comfortably across the full stack when a product demands it.
            </div>
        </div>

        <!-- Tags -->
        <div class="tags-container">
            <span class="tag">AI</span>
            <span class="tag">Docker</span>
            <span class="tag">SaaS Builder</span>
            <span class="tag">Node.js</span>
            <span class="tag">Python</span>
        </div>

        <!-- Accordion -->
        <button class="accordion-toggle">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                <polyline points="18 15 12 9 6 15"></polyline>
            </svg>
            Hide quick questions
        </button>

        <!-- Navigation Pills -->
        <div class="nav-grid">
            <button class="nav-pill">
                <svg class="nav-icon" viewBox="0 0 24 24" fill="none" stroke="#10b981" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><path d="M8 14s1.5 2 4 2 4-2 4-2"></path><line x1="9" y1="9" x2="9.01" y2="9"></line><line x1="15" y1="9" x2="15.01" y2="9"></line></svg>
                Me
            </button>
            <button class="nav-pill">
                <svg class="nav-icon" viewBox="0 0 24 24" fill="none" stroke="#10b981" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="7" width="20" height="14" rx="2" ry="2"></rect><path d="M16 21V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v16"></path></svg>
                Projects
            </button>
            <button class="nav-pill">
                <svg class="nav-icon" viewBox="0 0 24 24" fill="none" stroke="#6366f1" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="12 2 2 7 12 12 22 7 12 2"></polygon><polyline points="2 17 12 22 22 17"></polyline><polyline points="2 12 12 17 22 12"></polyline></svg>
                Skills
            </button>
            <button class="nav-pill">
                <svg class="nav-icon" viewBox="0 0 24 24" fill="none" stroke="#ec4899" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3l1.912 5.813a2 2 0 0 0 1.275 1.275L21 12l-5.813 1.912a2 2 0 0 0-1.275 1.275L12 21l-1.912-5.813a2 2 0 0 0-1.275-1.275L3 12l5.813-1.912a2 2 0 0 0 1.275-1.275L12 3z"></path></svg>
                Fun
            </button>
            <button class="nav-pill">
                <svg class="nav-icon" viewBox="0 0 24 24" fill="none" stroke="#f59e0b" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path><circle cx="12" cy="7" r="4"></circle></svg>
                Contact
            </button>
        </div>

        <!-- Spacer for fixed bottom input -->
        <div style="height: 80px;"></div>
    </div>

    <!-- Fixed Bottom Input -->
    <div class="input-area">
        <div class="avatar-small">N</div>
        <div class="input-wrapper">
            <input type="text" class="text-input" placeholder="Ask me anything...">
            <button class="send-btn">
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                    <line x1="5" y1="12" x2="19" y2="12"></line>
                    <polyline points="12 5 19 12 12 19"></polyline>
                </svg>
            </button>
        </div>
    </div>

</body>
</html>
